            ready: typeof window.getCurrentStory === 'function',
            version: this.version,
            timestamp: new Date().toISOString(),
          };
        },

        // 手动展开插件
        expand: function () {
          expandPlugin();
        },

        // 手动收缩插件
        collapse: function () {
          collapsePlugin();
        },
      };

      /**
       * 父页面监听iframe高度变化示例代码:
       *
       * window.addEventListener('message', function(event) {
       *   if (event.data.type === 'story-assistant-resize') {
