  /**
   * 处理剧情数据（开发环境）
   */
  function processPlotData(data) {
    // 处理新格式的数据结构
    const plotList = data.plotList || [];

    // 转换为标准格式 - 每个剧情包含其所有步骤
    stories = plotList.map((plot, index) => {
      // 找到当前执行的步骤
      const currentStep = plot.steps?.find(step => step.isExecute) || plot.steps?.[0] || {};

      return {
        id: plot.uniqueID,
        globalID: plot.globalID,
        title: plot.title,
        content: currentStep.event || '', // 当前步骤的事件作为内容
        description: plot.coreConflict || '',
        location: plot.location || '',
        participants: currentStep.characters ? currentStep.characters.split(',') : [],
        development: currentStep.development || '',
        steps: plot.steps || [],
        currentStepId: currentStep.stepId || '1',
        isExecuted: plot.steps?.some(step => step.isExecute) || false,
      };
    });

    // 按uniqueID排序
    stories.sort((a, b) => parseInt(a.id) - parseInt(b.id));

    // 设置currentPlot（来自数据源）
    const currentPlotData = data.currentPlot || {};
    currentPlot = currentPlotData.uniqueID || '0';
    currentStepId = currentPlotData.stepId || '1';

    console.log('📊 数据源currentPlot设置为：', currentPlot, 'stepId:', currentStepId);

    // 根据currentPlot设置当前剧情索引
    if (currentPlot !== '0') {
