  animation: blink 1.5s ease-in-out infinite;
}

/* 脉冲边框动画 */
@keyframes pulse-border {
  0%,
  100% {
    border-color: rgba(255, 149, 0, 0.3);
    box-shadow: 0 0 0 0 rgba(255, 149, 0, 0.1);
  }
  50% {
    border-color: rgba(255, 149, 0, 0.6);
    box-shadow: 0 0 0 4px rgba(255, 149, 0, 0.1);
  }
}

/* 闪烁提示动画 */
@keyframes blink {
  0%,
  100% {
    opacity: 0.8;
  }
  50% {
    opacity: 1;
  }
}

/* 标题与图标容器 */
.title-with-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

/* 未开始状态的图标 */
.no-plot-icon {
  font-size: 24px;
  color: #ff9500;
  animation: bounce 2s ease-in-out infinite;
  flex-shrink: 0;
}

@keyframes bounce {
  0%,
  20%,
  50%,
  80%,
  100% {
    transform: translateY(0);
  }
  40% {
    transform: translateY(-5px);
  }
  60% {
    transform: translateY(-3px);
  }
}

.story-title-wrapper {
  text-align: center;
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  cursor: pointer;
  padding: 8px;
  border-radius: 8px;
