}

.setting-item select {
  width: 100%;
  padding: 8px 12px;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  background: var(--surface-color);
  font-size: 16px;
  color: var(--text-primary);
}

.setting-item input[type='checkbox'] {
  margin-right: 8px;
  transform: scale(1.2);
}

.setting-item span {
  font-size: 16px;
  color: var(--text-primary);
}

.setting-description {
  margin-top: 6px;
}

.setting-description small {
  font-size: 12px;
  color: var(--text-secondary);
  line-height: 1.4;
  display: block;
