/**
 * 生产环境初始化
 * @returns {Promise<Object>} 包含数据或错误信息的对象
 */
async function initProductionEnvironment() {
  console.log('🚀 生产环境：开始初始化');

  try {
    // 检查必要的API是否可用
    if (typeof getCharWorldbookNames === 'undefined' || typeof getWorldbook === 'undefined') {
